<?php

namespace App\Http\Requests;

use App\Enums\EmployeeType;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * Body of employeeCreate / employeeUpdate (ADR-016 section 5). Creating needs the type and the names; updating changes the
 * names only. The code is generated by the server and the type is fixed at creation, so a request that sends `employee_code` at
 * all, or an `employee_type` on an update, is refused rather than ignored.
 */
class EmployeeInputRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    /** @return array<string, mixed> */
    public function rules(): array
    {
        $creating = $this->isMethod('POST');
        $required = $creating ? 'required' : 'sometimes';

        return [
            'employee_type' => $creating ? ['required', Rule::in(EmployeeType::values())] : ['prohibited'],
            'employee_code' => ['prohibited'],
            'first_name' => [$required, 'string', 'max:255', 'regex:/\S/'],
            'middle_name' => ['nullable', 'string', 'max:255'],
            'last_name' => [$required, 'string', 'max:255', 'regex:/\S/'],
        ];
    }

    /** @return array<string, string> */
    public function messages(): array
    {
        return [
            'employee_code.prohibited' => 'The code is generated by the system and cannot be set or changed.',
            'employee_type.prohibited' => 'The type of an employee cannot be changed.',
            'first_name.regex' => 'Enter a first name.',
            'last_name.regex' => 'Enter a last name.',
        ];
    }
}
